design.compositionCss:
/* Signal House: original cinema composition, inspired by expressive type and film-leader geometry. */
.shell{display:grid;grid-template-columns:204px minmax(0,1fr)}
.sidebar{display:flex;flex-direction:column;position:sticky;top:0;height:100dvh;gap:20px;padding:26px 14px;border:0;border-right:1px solid var(--weekly-soft);overflow-y:auto}
.brand{margin:0 0 12px}
.brand strong{font-family:var(--body);font-size:14px;font-weight:600;line-height:1.4}
.brand small{font-size:10px}
.sidebar nav{display:grid;grid-template-columns:minmax(0,1fr);gap:5px}
.nav-item:nth-child(n){display:flex;align-items:center;gap:10px;min-height:46px;padding:12px 10px;border:0;border-left:2px solid var(--weekly-soft);border-radius:0 8px 8px 0;transform:none;font-family:var(--body);font-size:12px;line-height:1.4;letter-spacing:0}
.nav-item span{font-family:var(--condensed);font-size:16px;min-width:21px;letter-spacing:0}
.nav-item.active{border-left-color:var(--weekly-mark)}
.sidebar-foot{display:grid;gap:8px;margin-top:auto;padding-top:18px;border:0}
.sidebar-foot .quiet{min-width:0;text-align:left;border-radius:8px}
main{max-width:1560px;margin:auto;padding:0 34px 80px}
.topbar{min-height:116px;padding:26px 0;margin-bottom:26px;border:0;border-bottom:1px solid var(--weekly-soft)}
.topbar h1{font-family:var(--body);font-weight:600;font-size:clamp(28px,3vw,40px);line-height:1.2;letter-spacing:-.04em;text-transform:none}
.eyebrow,.topbar .eyebrow,.panel .eyebrow{color:var(--weekly-mark)}
.primary,.quiet{border-radius:8px;min-height:44px}
.primary{background:var(--acid);color:var(--stage);border-color:var(--acid)}
.quiet{background:var(--panel);color:var(--ink);border-color:var(--weekly-soft)}
.panel,.module,.phase,.resource,.evidence-card,.production,.daily-review,.stat-card:nth-child(n),.cinema-film{padding:24px;border:1px solid var(--weekly-soft);border-radius:12px;box-shadow:none}
.panel h2,.intro-panel h2{font-family:var(--body);font-size:24px;font-weight:600;line-height:1.35;letter-spacing:-.03em;text-transform:none;border:0;padding-bottom:0}
.hero-grid:not(.daily-summary){grid-template-columns:minmax(0,1fr) minmax(180px,.32fr);gap:14px}
.poster-focus{grid-column:1;grid-row:1/4;min-height:560px;padding:34px;display:flex;flex-direction:column;align-items:start;border:1px solid var(--weekly-soft);border-bottom:5px solid var(--weekly-mark);border-radius:16px}
.poster-focus h2{font-family:var(--condensed);font-size:clamp(66px,7vw,96px);font-weight:400;line-height:1.04;letter-spacing:-.015em;max-width:650px;margin-bottom:26px;text-transform:uppercase}
.poster-focus h2 span{font-family:var(--script);font-size:.84em;font-style:italic;font-weight:600;line-height:1.1;letter-spacing:-.045em;text-transform:none;transform:none;margin:7px 0 0;padding:0;background:var(--stage);color:var(--acid)}
.poster-focus .hero-script{font-family:var(--body);font-size:15px!important;line-height:1.6;letter-spacing:.04em;margin:0 0 24px;transform:none}
.poster-focus .cinema-scene{width:60%;right:-8%;top:4%;opacity:.4;transform:none}
.poster-focus .hero-star{width:46px;height:46px;top:24px;right:24px;border:1px solid var(--weekly-mark);border-radius:50%;background:var(--stage);transform:rotate(15deg)}
.poster-focus .progress-wrap{width:100%;max-width:340px;margin-top:30px}
.hero-grid .stat-card{display:flex;flex-direction:column;grid-column:2;grid-row:auto;gap:8px;align-items:start;min-height:155px;padding:24px;background:var(--panel);border:1px solid var(--weekly-soft);border-left:3px solid var(--weekly-mark)}
.hero-grid .stat-card strong{font-family:var(--condensed);font-weight:400;font-size:54px;line-height:1;margin:8px 0;letter-spacing:0}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:10px;line-height:1.6}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:26px 0 32px;border:0}
.studio-programme button{min-height:112px;padding:22px!important;border:1px solid var(--weekly-soft)!important;border-bottom:3px solid var(--weekly-mark)!important;border-radius:12px;background:var(--panel);box-shadow:none}
.studio-programme span{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.module:nth-child(n){margin:0;border-top:3px solid var(--weekly-mark)}
.module h3{font-family:var(--condensed);font-size:32px;font-weight:400;line-height:1.2;letter-spacing:0;text-transform:none}
.module-head small{font-family:var(--body);font-size:11px;font-style:normal;line-height:1.6}
.topic{font-size:13px;line-height:1.6}
.roadmap{display:grid;columns:auto;grid-template-columns:minmax(0,1fr);gap:18px}
.phase:nth-child(n){display:grid;grid-template-columns:74px minmax(0,1fr) minmax(0,1.15fr);gap:22px;align-items:start;margin:0!important;padding:28px;min-height:0;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:12px;transform:none}
.phase h3{font-family:var(--script);font-size:34px;font-weight:600;line-height:1.15;letter-spacing:-.03em;margin:0}
.phase small{font-family:var(--condensed);font-size:22px;letter-spacing:0}
.phase ul{margin:0}
.resource-list{grid-template-columns:minmax(0,1fr);gap:18px}
.resource{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:22px;align-items:start;padding:26px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark)}
.resource h3{font-family:var(--body);font-size:18px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.resource div{margin-bottom:0}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card label{font-family:var(--body);font-size:15px;line-height:1.5}
.cinema-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;border:0}
.cinema-film{padding:18px}
.cinema-film:nth-child(n) .film-cover{transform:none}
.film-cover{min-height:310px;border:0;border-bottom:3px solid var(--weekly-mark);border-radius:8px;box-shadow:none;background:var(--weekly-soft)}
.cinema-film .film-cover h3{font-family:var(--script);font-size:42px;font-weight:600;line-height:1.1;letter-spacing:-.035em;text-transform:none}
.film-cover h3 small,.cover-caption{color:var(--ink)}
.cover-caption{letter-spacing:.08em}
.cinema-intro{padding:34px;border:1px solid var(--weekly-soft);border-radius:16px}
.cinema-intro h2{font-family:var(--condensed);font-size:clamp(44px,5vw,68px);font-weight:400;line-height:1.15;letter-spacing:0}
.cinema-source-note,.cinema-credits,.meta,.studio-footer{color:var(--ink)}
.journal-masthead{padding:30px 0;border-bottom:1px solid var(--weekly-soft)}
.journal-masthead h2{font-family:var(--condensed);font-size:clamp(72px,8vw,110px);font-weight:400;line-height:1.12;letter-spacing:-.02em}
.journal-masthead h2 em{display:block;font-family:var(--script);font-size:.78em;font-style:italic;font-weight:600;line-height:1.2;letter-spacing:-.045em;transform:none;padding:0;background:var(--paper);color:var(--ink)}
.journal-seal{border:1px solid var(--weekly-mark);border-radius:50%;background:var(--panel);transform:rotate(-7deg)}
.journal-workbench{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:24px}
.journal-bridge{transform:none}
.journal-section-title{border-top:1px solid var(--weekly-soft)}
.journal-section-title h2{font-family:var(--body);font-size:25px;font-weight:600;line-height:1.3;letter-spacing:-.03em}
#view-journal .journal-deck{gap:22px;border:0}
.diary-card:not(.poster-card){transform:none;margin:0;padding:24px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:12px;box-shadow:none}
.diary-card:not(.poster-card) h3{font-family:var(--script);font-size:46px;font-weight:600;line-height:1.1;text-transform:none}
#view-journal .diary-card.poster-card{border-radius:8px}
.journal-empty{border-color:var(--weekly-soft);border-radius:12px}
.journal-empty h3{font-size:44px;line-height:1.2}
.form-panel input,.form-panel select,.form-panel textarea,.filter-row input,.filter-row select{border:1px solid var(--weekly-soft);border-radius:8px;background:var(--stage);color:var(--ink)}
.filter-row{border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.tag{border-radius:5px}
@media(max-width:1100px) and (min-width:761px){
.shell{grid-template-columns:184px minmax(0,1fr)}
.sidebar nav{grid-template-columns:minmax(0,1fr)}
main{padding:0 24px 64px}
.hero-grid:not(.daily-summary){grid-template-columns:minmax(0,1fr)}
.poster-focus{grid-column:1;grid-row:auto;min-height:490px}
.hero-grid .stat-card{grid-column:auto;min-height:130px}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
.cinema-grid,.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.phase:nth-child(n){grid-template-columns:60px minmax(0,1fr)}
.phase ul{grid-column:2}
.resource{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:760px){
.shell{display:block}
.sidebar{display:block;position:relative;height:auto;padding:20px;border:0;border-bottom:1px solid var(--weekly-soft)}
.brand{margin:0}
.sidebar-foot{display:flex;flex-wrap:wrap;margin-top:14px;padding:0}
.sidebar-foot .quiet{font-size:10px;padding:10px}
main{padding:0 20px 64px}
.topbar{min-height:0;padding:24px 0;margin-bottom:20px}
.topbar h1{font-size:28px;line-height:1.3}
.top-actions{margin-top:14px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:480px;padding:28px 22px;border:1px solid var(--weekly-soft);border-bottom:4px solid var(--weekly-mark);border-radius:14px}
.poster-focus h2{font-size:clamp(54px,15vw,74px);line-height:1.08}
.poster-focus h2 span{font-size:.88em;line-height:1.15;margin-top:8px}
.poster-focus .hero-script{font-size:14px!important}
.poster-focus .cinema-scene{width:80%;right:-18%;opacity:.3}
.poster-focus .hero-star{width:30px;height:30px}
.hero-grid .stat-card{display:flex;flex-direction:column;grid-column:auto;grid-row:auto;align-items:start;gap:6px;min-height:124px;padding:16px 10px;border-left:1px solid var(--weekly-soft);border-bottom:3px solid var(--weekly-mark)}
.hero-grid .stat-card strong{font-size:34px;margin:4px 0}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:9px;letter-spacing:0}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:16px}
.studio-programme button{min-height:98px;padding:22px!important}
.panel,.module,.resource,.evidence-card,.production,.daily-review,.cinema-film{padding:22px}
.panel h2,.intro-panel h2{font-size:23px;line-height:1.35}
.phase:nth-child(n){display:block;min-height:0;padding:24px}
.phase h3{font-size:32px;margin:16px 0}
.module h3{font-size:30px}
.phase ul{margin-top:15px}
.resource{display:block}
.resource div{margin-bottom:16px}
.resource h3{font-size:17px}
.film-cover{min-height:280px}
.cinema-film .film-cover h3{font-size:43px;line-height:1.1}
.journal-masthead h2{font-size:clamp(58px,16vw,80px);line-height:1.18;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.8em}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:nth-child(n){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:34px 14px}
#view-journal .journal-empty h3{font-size:38px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
